  --text-link:       #70B5F9;
  --text-disabled:   rgba(255,255,255,0.32);

  /* Border */
  --border-default: rgba(255,255,255,0.10);
  --border-subtle:  rgba(255,255,255,0.06);
  --border-strong:  rgba(255,255,255,0.22);
  --border-focus:   #70B5F9;
}

